#include <map>
#include <string>

struct Data { /* No default constructor */ };

int main() {
    std::map<std::string, float> stocks;

    // 1. Inefficient Insertion (Default construction + Assignment)
    stocks["BASF"] = 369.50; // O(log N) total time

    // 2. Efficient Insertion (Direct construction)
    stocks.insert({"VW", 413.50}); // Preferred for new elements

    // 3. Requirement Failure (If Data lacked a default ctor)
    // std::map<int, Data> data_map;
    // data_map[1] = Data(5); // Error: Requires Data()
}
